import EventService from"./EventService.js";export default class ResizeObserverService{constructor(options){this._selector=options.selector||"#dyjsform";this.targetElement=document.querySelector(this._selector);if(!this.targetElement){throw new Error(`Element with selector ${this._selector} not found.`)}this._eventService=new EventService(options);this._inputResizedTimeout=0;this.observerForNewElements=new MutationObserver((()=>{this.targetElement.querySelectorAll(".dyjsform_input").forEach((targetInput=>{if(!targetInput.__mutationObserver){const observer=new MutationObserver((()=>{clearTimeout(this._inputResizedTimeout);this._inputResizedTimeout=setTimeout((()=>{this.inputResized(targetInput)}),100)}));observer.observe(targetInput,{attributes:true,attributeFilter:["style"]});targetInput.__mutationObserver=observer}}))}));this.observerForNewElements.observe(this.targetElement,{childList:true,subtree:true})}inputResized(targetInput){const eventName=`ResizeObserverService.inputResized`;this._eventService.dispatchEvent(eventName,{element:targetInput,message:"Element resized"})}disconnect(){this.observerForNewElements.disconnect()}}